struct Node;

/// Hosts this node's `with` clause grants. Requests outside this set are not
/// sent: the host would trap on them, and a trap would fail the whole run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extracts the lowercased host from an http(s) URL without pulling in a URL
/// parser. Returns `None` for anything this simple parser does not accept.
fn host_of(url: &str) -> Option<String> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;

    let end = rest
        .find(|c: char| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];

    // Drop any userinfo: the host is whatever follows the last '@'.
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };

    // IPv6 literals are never on the allowlist.
    if host_port.starts_with('[') {
        return None;
    }

    // Drop the port, if any.
    let host = match host_port.find(':') {
        Some(i) => &host_port[..i],
        None => host_port,
    };

    if host.is_empty() {
        return None;
    }
    Some(host.to_ascii_lowercase())
}

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            let allowed = host_of(&url)
                .map(|h| ALLOWED_HOSTS.contains(&h.as_str()))
                .unwrap_or(false);

            if !allowed {
                failures.push(FetchFailure {
                    url,
                    error: "host outside granted allowlist".to_string(),
                });
                continue;
            }

            match aap::caps::http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
